style.css:
@-moz-document domain("instagram.com") {
/* Set the background image for the entire page */
  body {
    background: url('https://i.pinimg.com/474x/5b/f6/12/5bf612f09cd851bbbffd60d173331019.jpg') no-repeat center center fixed;
    background-size: cover;
  }

  /* Set the header background */
  header {
    background: url('https://i.pinimg.com/474x/5b/f6/12/5bf612f09cd851bbbffd60d173331019.jpg') no-repeat center center;
    background-size: cover;
  }

  /* Change text color */
  * {
    color: #c10909 !important;
  }

  /* Change button colors */
  button, .button, [role="button"] {
    background-color: #c10909 !important;
    color: #ffffff !important;
    border: 1px solid #c10909 !important;
  }

  button:hover, .button:hover, [role="button"]:hover {
    background-color: #fa3030 !important;
    border-color: #fa3030 !important;
  }

  /* Highlight color for focus/active elements */
  *:focus, *:active {
    outline-color: #fa3030 !important;
  }

  /* Additional adjustments for inputs */
  input, textarea {
    border: 1px solid #c10909 !important;
    background-color: #fa3030 !important;
    color: #ffffff !important;
  }

  input::placeholder, textarea::placeholder {
    color: #c10909 !important;
  }
}
